    public function svg(string$value):string{if($value===''||strlen($value)>64||preg_match('/^[\x20-\x7E]+$/D',$value)!==1)throw new \InvalidArgumentException('El código no se puede representar como Code 128.');$codes=[104];$checksum=104;foreach(str_split($value)as$i=>$char){$code=ord($char)-32;$codes[]=$code;$checksum+=$code*($i+1);}$codes[]=$checksum%103;$codes[]=106;$x=10;$bars='';foreach($codes as$code){$pattern=self::P[$code];foreach(str_split($pattern)as$i=>$width){$w=(int)$width;if($i%2===0)$bars.='<rect x="'.$x.'" y="4" width="'.$w.'" height="48"/>';$x+=$w;}}$width=$x+10;return'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 '.$width.' 68" role="img" aria-label="Código '.$this->xml($value).'"><rect width="100%" height="100%" fill="white"/>'.$bars.'<text x="'.($width/2).'" y="64" text-anchor="middle" font-family="monospace" font-size="9">'.$this->xml($value).'</text></svg>';}
    private function xml(string$value):string{return htmlspecialchars($value,ENT_QUOTES|ENT_XML1,'UTF-8');}
